  if (!/二家[賓宾]客[，,、\s]*互相[譏讥譥]揣[，,、\s]*遂各[樹树]朋徒/.test(source)) return
  const scenes = Array.isArray(candidate.scenes) ? candidate.scenes                 
    : Array.isArray(candidate.__storyboardSegments) ? candidate.__storyboardSegments                  : [candidate]
  const problems           = []
  for (const scene of scenes) {
