const url = String(${first_frame_branch.previousLastFrame} || '').trim()
if (!url) throw new Error('首帧图截取尾帧节点未收到可用的前镜尾帧')
return {
  url,
  requestedMode: 'reuse_previous_tail',
  resolvedMode: 'reuse_previous_tail',
  generated: false,
  source: 'previous-shot-tail',
